const fs = require('fs');
const { chromium } = require('playwright');
const axe = require('axe-core');

(async () => {
  const html = fs.readFileSync('index.html', 'utf8');
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.setContent(html, { waitUntil: 'load' });
  await page.addScriptTag({ content: axe.source });

  const checks = {
    dialogClosedByDefault: await page.$eval('#confirm-dialog', el => !el.open),
    triggerHasClass: await page.$eval('#delete-trigger', el => el.classList.contains('trigger')),
  };

  await page.click('#delete-trigger');
  checks.dialogOpenAfterClick = await page.$eval('#confirm-dialog', el => el.open);
  await page.keyboard.press('Escape');
  checks.dialogClosedAfterEscape = await page.$eval('#confirm-dialog', el => !el.open);

  const results = await page.evaluate(async () => await window.axe.run(document));
  const violations = results.violations.filter(v => !(v.tags || []).includes('best-practice'));
  const bp = results.violations.filter(v => (v.tags || []).includes('best-practice'));
  console.log(JSON.stringify({ checks, violations, bestPractice: bp.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) })) }, null, 2));
  await browser.close();
  if (violations.length) process.exit(1);
})();
